CREATE TABLE IF NOT EXISTS cms_content (name VARCHAR(20) PRIMARY KEY, body LONGTEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cms_admin (id TINYINT UNSIGNED PRIMARY KEY, username VARCHAR(64) NOT NULL, password_hash VARCHAR(255) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cms_attempts (ip CHAR(64) NOT NULL, bucket BIGINT NOT NULL, n INT UNSIGNED NOT NULL, PRIMARY KEY (ip,bucket)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cms_media (id CHAR(32) PRIMARY KEY, mime VARCHAR(32) NOT NULL, bytes INT UNSIGNED NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
